                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.zouk_new_unicommerce_factitems_intermediate AS with Combined as ( select Billing_Address_Pincode AS Pincode, Billing_Address_Country AS Country, Billing_Address_State AS State, Billing_Address_City as City, Billing_Address_Phone AS Phone, Billing_Address_Name AS Name, Notification_Email AS Email, Updated AS Shipping_Last_Update_Date, Item_SKU_Code AS SKU, Seller_SKU_Code as Marketplace_SKU, Bundle_SKU_Code_Number AS Combo_SKU, Combination_Description AS Combo_Name, Channel_Product_Id AS Product_Id, Item_Type_Name AS PRODUCT_NAME, Currency, UPPER(Sale_Order_item_Status) AS Order_Status, Invoice_Code, cast(nullif(Invoice_Created,\"\") as datetime) AS Invoice_Date, cast(nullif(Created,\"\") as datetime) AS Initial_Order_Date, cast(nullif(Order_Date_as_dd_mm_yyyy_hh_MM_ss,\"\") as datetime) AS Order_Date, replace(Sale_Order_Code,\'`\',\'\') as Order_Id, replace(Display_Order_Code,\'`\',\'\') AS Reference_Code, cast(Shipping_Charges as float64) AS Shipping_Price, safe_cast(Discount as float64) as Discount, Voucher_Code as Discount_Codes, safe_cast(Tax_Value as float64) AS Tax, 1 AS Quantity, safe_CAST(Selling_Price as FLOAT64) as Selling_Price, UPPER(REPLACE(Channel_Name,\" \",\"_\")) AS Marketplace, replace(Sale_order_item_code,\"`\",\"\") AS Sale_order_item_code, Shipping_Package_Code, Shipping_Package_Status_Code as Shipping_Package_Status, Reverse_Pickup_Code, cast(nullif(Reverse_Pickup_Created_Date,\"\")as datetime) AS Reverse_Pickup_Created_Date, Tracking_Number AS AWB, Facility as Warehouse_Name, CASE WHEN cod = \"0\" then \'PREPAID\' else \'COD\' END as Payment_Mode, Shipping_Courier AS COURIER, Dispatch_Date, delivery_time As Delivered_Date, Fulfillment_TAT, sale_order_item_status, Shipping_Tracking_Status as Shipping_Status, \'Sale Order\' AS Report_Type from `MapleMonk.zouk_db_updated_get_sale_orders` fi Union All select Shipping_Address_Pincode AS Pincode, Shipping_Address_Country AS Country, Shipping_Address_State AS State, Shipping_Address_City as City, Shipping_Address_Phone AS Phone, SHipping_Address_Name AS Name, Null AS Email, Null AS Shipping_Last_Update_Date, g.Product_SKU_Code AS SKU, Null as Marketplace_SKU, Bundle_SKU_Code_Number AS Combo_SKU, Null AS Combo_Name, null AS Product_Id, Product_Name AS PRODUCT_NAME, Currency, CASE WHEN r.Return_Code is not null then \'Cancelled\' ELSE \'Invoiced\' END AS Order_Status, Invoice_Number AS Invoice_Code, PARSE_DATETIME(\'%d-%m-%Y\', NULLIF(Date, \'\')) AS Invoice_Date, PARSE_DATETIME(\'%d-%m-%Y\', NULLIF(Date, \'\')) AS Initial_Order_Date, PARSE_DATETIME(\'%d-%m-%Y\', NULLIF(Date, \'\')) AS Order_Date, replace(Sale_Order_Number,\'`\',\'\') as Order_Id, replace(Display_Sale_Order_Number,\'`\',\'\') AS Reference_Code, cast(Null as float64) AS Shipping_Price, safe_cast(null as float64) as Discount, Null as Discount_Codes, safe_cast(null as float64) AS Tax, SAFE_CAST(Qty AS FLOAT64) AS Quantity, safe_CAST(Sales As FLOAT64) as Selling_Price, UPPER(REPLACE(Channel_Ledger,\" \",\"_\")) AS Marketplace, concat(Sale_Order_Number,Invoice_number,g.Product_SKU_Code) AS Sale_order_item_code, Null As Shipping_Package_Code, Null as Shipping_Package_Status, r.Return_Code AS Reverse_Pickup_Code, r.Return_Date AS Reverse_Pickup_Created_Date, Null AS AWB, Null as Warehouse_Name, Payment_Method AS Payment_Mode, Shipping_Provider AS COURIER, Null AS Dispatch_Date, Null AS Delivered_Date, Null AS Fulfillment_TAT, Null AS sale_order_item_status, Null as Shipping_Status, \'B2B Tally GST\' AS Report_Type FROM `MapleMonk.uc_get_tally_gst_report` g LEFT JOIN ( SELECT PARSE_DATETIME(\'%d-%m-%Y\', NULLIF(date, \'\')) AS Return_Date, Sale_Order_Number AS Order_Number, Product_SKU_Code, Invoice_number AS Return_Invoice, Original_Invoice_No, RP_Code AS Return_Code, \'Cancelled\' AS Order_Status FROM `MapleMonk.uc_get_tally_return_gst_report` QUALIFY ROW_NUMBER() OVER ( PARTITION BY Original_Invoice_No, LOWER(TRIM(Product_SKU_Code)) ORDER BY Date DESC ) = 1 ) r ON g.Invoice_number = r.Original_Invoice_No AND LOWER(TRIM(g.Product_SKU_Code)) = LOWER(TRIM(r.Product_SKU_Code)) ) Select c.*, coalesce(upper(mm.final_marketplace), upper(c.Marketplace)) FINAL_MARKETPLACE, UPPER(mm.Marketplace_segments) MARKETPLACE_SEGMENT, UPPER(mm.type_of_Sale) TYPE_OF_SALE, UPPER(mm.Mode_Of_Business_1) AS Mode_Of_Business1, UPPER(mm.Mode_Of_Business_2) AS Mode_Of_Business2, UPPER(mm.Channel) AS Channel, UPPER(mm.Grouped_Channel) AS Grouped_Channel From Combined c LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from `MapleMonk.Zouk_db_New_Marketplace_Mapping` ) where rw =1 ) mm ON trim(UPPER(REPLACE(c.Marketplace,\" \",\"_\"))) = trim(Upper(mm.marketplace)) ; CREATE OR REPLACE TABLE maplemonk.zouk_UNICOMMERCE_RETURNS_INTERMEDIATE AS WITH New_UC AS ( SELECT fi.Marketplace, cast(NULL as string) AS source, fi.order_id, fi.Invoice_Code, fi.Phone, fi.email, fi.Order_Date, fi.reference_code, fi.Reverse_Pickup_Code AS return_display_code, cast(NULL as string) AS return_status, cast(NULL as datetime) AS inventory_received_date, fi.Reverse_Pickup_Created_Date AS return_complete_date, fi.Selling_Price, fi.Quantity, cast(NULL as string) AS return_invoice_display_code, cast(NULL as string) AS return_courier, cast(NULL as string) AS return_provider_shipping_status, cast(NULL as string) AS return_tracking_number, cast(NULL as string) AS return_type, fi.sale_order_item_code, fi.sku AS item_sku, fi.PRODUCT_NAME AS item_name, fi.Combo_SKU, fi.Combo_Name, UPPER(cid.category_code) AS category_code, UPPER(cid.CATEGORY) AS Product_Category, cast(NULL as string) AS inventory_type, \'new uc\' AS Type FROM MapleMonk.zouk_new_unicommerce_factitems_intermediate fi LEFT JOIN ( SELECT * FROM ( SELECT commonsku AS skucode, name, brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE, ROW_NUMBER() OVER ( PARTITION BY commonsku ORDER BY LENGTH(IFNULL(Category_Code, \'\')) DESC ) AS rw FROM `zouk-wh.maplemonk.final_sku_master` ) WHERE rw = 1 ) cid ON LOWER(fi.sku) = LOWER(cid.skucode) WHERE fi.Reverse_Pickup_Created_Date IS NOT NULL AND LOWER(fi.Order_Status) LIKE \'%cancel%\' ), New_UC_Keys AS ( SELECT DISTINCT TRIM(UPPER(REPLACE(IFNULL(order_id, \'\'), \'`\', \'\'))) AS k_order_id, TRIM(UPPER(REPLACE(IFNULL(item_sku, \'\'), \'`\', \'\'))) AS k_sku FROM New_UC ), Old_UC AS ( SELECT Marketplace, source, order_id, cast(NULL as string) AS Invoice_Code, Phone, email, Order_Date, Reference_Code, return_display_code, return_status, inventory_received_date, return_complete_date, NULL AS Selling_Price, NULL AS Quantity, return_invoice_display_code, return_courier, return_provider_shipping_status, return_tracking_number, return_type, sale_order_item_code, item_sku, item_name, cast(NULL as string) AS Combo_SKU, cast(NULL as string) AS Combo_Name, cast(NULL as string) AS category_code, cast(NULL as string) AS Product_Category, inventory_type, \'Old uc\' AS Type FROM maplemonk.zouk_UNICOMMERCE_RETURNS_INTERMEDIATE old WHERE NOT EXISTS ( SELECT 1 FROM New_UC_Keys nk WHERE nk.k_order_id = TRIM(UPPER(REPLACE(IFNULL(old.order_id, \'\'), \'`\', \'\'))) AND nk.k_sku = TRIM(UPPER(REPLACE(IFNULL(old.item_sku, \'\'), \'`\', \'\'))) ) ) SELECT * FROM New_UC UNION ALL SELECT * FROM Old_UC ; Create Or Replace Table `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` as SELECT pincode ,marketplace ,source ,order_id ,reference_code ,phone ,name ,email ,SHIPPING_LAST_UPDATE_DATE ,sku ,Marketplace_sku ,product_id ,product_name ,null as Combo_SKU ,null as Combo_Name ,currency ,city ,state ,ORDER_STATUS ,invoiceCode ,invoiceDate ,null as return_complete_date ,initial_order_date ,order_date ,shipping_price ,SUBORDER_QUANTITY ,discount ,Null as Discount_Codes ,tax ,SELLING_PRICE ,shippingPackageCode ,shippingPackageStatus ,saleOrderItemCode ,SALES_ORDER_ITEM_ID ,AWB ,warehouse_name ,payment_mode ,payment_method ,courier ,shipping_status ,shippedQuantity ,Dispatch_date ,Delivered_Date ,return_flag ,return_quantity ,cancelled_quantity ,new_customer_flag ,acquisition_product ,days_in_shipment ,FINAL_MARKETPLACE ,MARKETPLACE_SEGMENT ,TYPE_OF_SALE ,Mode_of_Business1 ,Mode_Of_Business2 ,Channel ,Grouped_Channel FROM `MapleMonk.zouk_UNICOMMERCE_fact_items_intermediate_final` WHERE NOT (TRIM(UPPER(CONCAT(ifnull(reference_code,\"\"),(ifnull(saleOrderItemCode,\"\"))))) IN ( SELECT DISTINCT TRIM(UPPER(CONCAT(ifnull(reference_code,\"\"),(ifnull(sale_Order_Item_Code,\"\"))))) FROM MapleMonk.zouk_new_unicommerce_factitems_intermediate )) UNION ALL SELECT pincode, Marketplace, Marketplace as Source, Order_Id, o.reference_code, Phone, Name, email, CAST(NULLIF(Shipping_Last_Update_Date, \"\") AS DATETIME) as Shipping_Last_Update_Date, SKU, marketplace_sku, product_id, Product_name, Combo_SKU, Combo_Name, currency, city, State, case when os.sale_order_item_code is not null then \'RETURNED\' else o.ORDER_STATUS end as ORDER_STATUS, Invoice_Code as invoiceCode, Invoice_Date as invoiceDate, Reverse_Pickup_Created_Date as return_complete_date, Initial_Order_Date as Initial_Order_Date, CASE WHEN LOWER(TYPE_OF_SALE) LIKE \'%primary%\' THEN o.invoice_Date ELSE o.order_date END AS order_date, shipping_price, Quantity as suborder_quantity, discount, Discount_Codes, tax, Selling_Price, Shipping_Package_Code as shippingPackageCode, Shipping_Package_Status as shippingPackageStatus, o.Sale_order_item_code as saleOrderItemCode, null as sales_order_item_id, AWB, warehouse_name, payment_mode, null as Payment_method, COURIER, Shipping_Status, null as shippedQuantity, CAST(NULLIF(Dispatch_Date, \"\") AS DATETIME) as Dispatch_Date, CAST(NULLIF(Delivered_Date, \"\") AS DATETIME) as Delivered_Date, null as return_flag, null as return_quantity, null as cancelled_quantity, null as new_customer_flag, null as acquisition_product, null as days_in_shipment, FINAL_MARKETPLACE, MARKETPLACE_SEGMENT, TYPE_OF_SALE, Mode_Of_Business1, Mode_Of_Business2, Channel, Grouped_Channel FROM MapleMonk.zouk_new_unicommerce_factitems_intermediate o left join ( select reference_code ,sale_order_item_code from maplemonk.zouk_UNICOMMERCE_RETURNS_INTERMEDIATE qualify row_number() over(partition by lower(reference_code),lower(sale_order_item_code) order by 1) =1 )os on lower(o.reference_code) = lower(os.reference_code) and loweR(os.sale_order_item_code) = lower(o.sale_Order_Item_Code) ; create or replace table maplemonk.zouk_customerID_test_Final as with new_phone_numbers as ( select contact_num ,9700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct SUBSTR(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) as contact_num from `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` ) a ), int as ( select contact_num,email,coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email,maple_monk_id,9800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10)) as contact_num, e.email,maple_monk_id from ( select replace(phone,\' \',\'\') as contact_num,email from `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` ) e left join new_phone_numbers p on p.contact_num = SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) ) a ) b ) select contact_num,email,case when email is not null and email <> \'\' then min(maple_monk_id) over (partition by email ) else maple_monk_id end maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` as select coalesce(c.maple_monk_id,c.maple_monk_id) customer_id, o.*, min(order_date) over(partition by coalesce(c.maple_monk_id,c.maple_monk_id)) as acquisition_date from `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` o left join (select distinct contact_num phone,maple_monk_id from maplemonk.zouk_customerID_test_Final )c on replace(c.phone,\' \',\'\') = replace(o.phone,\' \',\'\') where o.order_date is not null; CREATE OR REPLACE TABLE `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` as select fi.*, upper(coalesce(p.Brand,pid.Brand,cid.Brand)) AS Brand, coalesce(p.SKUCODE,pid.skucode,pid.skucode,fi.SKU) AS SKU_CODE, coalesce(p.name, pid.name,cid.name,fi.product_name) as PRODUCT_NAME_Final, Upper(coalesce(p.CATEGORY,pid.CATEGORY,cid.CATEGORY)) AS Product_Category, Upper(coalesce(p.SUB_CATEGORY,pid.SUB_CATEGORY,cid.SUB_CATEGORY)) AS Product_Sub_Category, Upper(coalesce(p.collection,pid.collection,cid.collection)) AS collection, Upper(coalesce(p.print,pid.print,cid.print)) AS print, Upper(coalesce(p.category_code,pid.category_code,cid.category_code)) AS category_code, Upper(coalesce(p.product_type,pid.product_type,cid.product_type)) AS product_type, (coalesce(p.BAU_OFFLINE,pid.BAU_OFFLINE,cid.BAU_OFFLINE)) AS BAU_OFFLINE, (coalesce(p.BAU_ONLINE,pid.BAU_ONLINE,cid.BAU_ONLINE)) AS BAU_ONLINE, (coalesce(p.TAX_RATE,pid.TAX_RATE,cid.TAX_RATE)) AS FINAL_TAX_RATE, coalesce(ofsm.tax_rate,p.tax_rate,pid.TAX_RATE,cid.TAX_RATE,case when order_date < \'2025-09-22\' then 0.12 else 0.05 end) AS Tax_Rate, (coalesce(p.Type,pid.Type,cid.Type)) AS SKU_Type, Upper(coalesce(p.commonsku,pid.commonsku,cid.commonsku)) AS commonsku, Upper(coalesce(pid.category_code,cid.category_code)) AS child_category_code, latest.updated_order_status, latest.status_date from `MapleMonk.zouk_UNICOMMERCE_FACT_ITEMS` fi left join (select * from (select marketplace_sku skucode, name,brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE, Type , row_number() over (partition by marketplace_sku order by length(ifnull(Category_Code,\'\')) desc ) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) p on lower(fi.Marketplace_sku) = lower(p.skucode) left join (select * from (select marketplace_sku skucode, name,brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE, Type , row_number() over (partition by marketplace_sku order by length(ifnull(Category_Code,\'\')) desc ) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) pid on lower(fi.sku) = lower(pid.skucode) left join (select * from (select commonsku skucode, name,brand, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE, Type , row_number() over (partition by commonsku order by length(ifnull(Category_Code,\'\')) desc ) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) cid on lower(fi.sku) = lower(cid.skucode) left join (Select * from ( select *,row_number() over(partition by lower(ifnull(commonsku,\'\')) order by 1)rw from `MapleMonk.FINAL_SKU_MASTER_TEMP` )where rw = 1 ) ofsm on lower(fi.sku) = lower(ifnull(ofsm.commonsku,\'\')) and Date(order_date) < \'2025-09-22\' LEFT JOIN ( SELECT Shipping_Package_Code, Display_Order_Code, time_stamp AS status_date, new_value AS updated_order_status FROM ( SELECT Shipping_Package_Code, Display_Order_Code, time_stamp, new_value, ROW_NUMBER() OVER ( PARTITION BY Shipping_Package_Code, Display_Order_Code, DATE(time_stamp) ORDER BY time_stamp DESC ) AS rn FROM `MapleMonk.zouk_db_get_shipping_package_timeline` ) WHERE rn = 1 ) latest ON LOWER(fi.reference_code) = LOWER(latest.Display_Order_Code) AND LOWER(fi.ShippingPackageCode) = LOWER(latest.Shipping_Package_Code) ;",
                    "transaction": true
